package com.peopleai.candidates.controller;
import com.peopleai.candidates.model.Candidate;import com.peopleai.candidates.repository.CandidateRepository;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/candidates") @CrossOrigin(origins="*") public class CandidatesController{private final CandidateRepository repo;public CandidatesController(CandidateRepository r){repo=r;}@GetMapping public List<Candidate> all(){return repo.findAll();}@GetMapping("/{id}")public Candidate one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Candidate create(@Valid @RequestBody Candidate x){return repo.save(x);}@PutMapping("/{id}")public Candidate update(@PathVariable Long id,@Valid @RequestBody Candidate x){Candidate c=one(id);c.setName(x.getName());c.setRole(x.getRole());c.setScore(x.getScore());c.setLocation(x.getLocation());c.setEmail(x.getEmail());c.setStatus(x.getStatus());return repo.save(c);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){repo.delete(one(id));}}
